namespace VtuberBot.Core; public sealed record AppEvent(string Name,object?Payload=null); public sealed class EventManager{readonly object g=new();readonly Dictionary<string,List<Action<AppEvent>>> h=[];readonly ILogger l;public EventManager(ILogger x)=>l=x;public void Subscribe(string n,Action<AppEvent>a){ArgumentNullException.ThrowIfNull(a);lock(g){if(!h.TryGetValue(n,out var q))h[n]=q=[];if(!q.Contains(a))q.Add(a);}}public void Unsubscribe(string n,Action<AppEvent>a){lock(g){if(h.TryGetValue(n,out var q)){q.Remove(a);if(q.Count==0)h.Remove(n);}}}public void Emit(AppEvent e){Action<AppEvent>[]q;lock(g)q=h.TryGetValue(e.Name,out var x)?x.ToArray():[];foreach(var a in q)try{a(e);}catch(Exception ex){l.Error(ex,"Event handler failed for {0}",e.Name);}}}